// L leg -- SCR-114 CHECKMULTISIG stack layout, limits and depth checks.
//
// REVIEWED TRANSLITERATION of Bitcoin.Interpreter.Defs.checkMultiSig front
// matter, spec/core/Bitcoin/Interpreter/Defs.lean:1071-1096 at this repo_head.
// NOT generated by twin/gen.py: twin/ops_ir.py has no CHECKMULTISIG handler
// (wires 0xae/0xaf map to OP_UNSUPPORTED_CHECKSIG).
//
//   checkMultiSig ctx w st :=
//     if ctx.sv = .tapscript then .error .tapscriptCheckMultiSig   -- other cell
//     else if st.stack.length < 1 then .error .stackUnderflow
//     else match decodeNum ctx.pol (topAt st.stack 1) 4 with
//       | .ok nkv =>
//         if nkv < 0 ∨ MAX_PUBKEYS_PER_MULTISIG < nkv then .error .pubKeyCount
//         else let nKeys := nkv.toNat
//              let opCount₂ := st.opCount + nKeys
//              if MAX_OPS_PER_SCRIPT < opCount₂ then .error .opCount
//              else if st.stack.length < nKeys + 2 then .error .stackUnderflow
//              else match decodeNum (st.stack[nKeys+1]!) 4 with
//                | .ok nsv =>
//                  if nsv < 0 ∨ nKeys < nsv then .error .sigCount
//                  else let nSigs := nsv.toNat
//                       if st.stack.length < nKeys + nSigs + 3 then
//                         .error .stackUnderflow
//                       else <FindAndDelete, cmsLoop, cmsCleanup ...>
//
// Lean's stack is top-first; the C slice's `ikey2 = nKeys+2` and
// `isig = nKeys+3` are the same positions expressed bottom-first, which is why
// this leg derives them from the count rather than from a cursor.  Sigversion
// is base or witness-v0; `.tapscript` is rejected before this fragment and is
// proved by the separate ban cell.
#include <cstdint>
#include "cms_obs.h"

enum {
  LAY_OK = 0,
  LAY_PUBKEY_COUNT = 1,
  LAY_OP_COUNT = 2,
  LAY_UNDERFLOW = 3,
  LAY_SIG_COUNT = 4
};

extern "C" uint64_t cell_cms_layout(int32_t nKeysIn, int32_t nSigsIn,
                                    uint32_t stackSize, uint32_t opCount) {
  const uint64_t depth = (uint64_t)stackSize;
  if (depth < 1u) return cms_pack_layout(LAY_UNDERFLOW, 0, 0, 0, 0);
  const int64_t nkv = (int64_t)nKeysIn;              // decodeNum .ok arm
  if (nkv < 0 || 20 < nkv) return cms_pack_layout(LAY_PUBKEY_COUNT, 0, 0, 0, 0);
  const uint32_t nKeys = (uint32_t)nkv;
  const uint64_t opCount2 = (uint64_t)opCount + (uint64_t)nKeys;
  if (201u < opCount2) return cms_pack_layout(LAY_OP_COUNT, 0, 0, 0, 0);
  if (depth < (uint64_t)nKeys + 2u) {
    return cms_pack_layout(LAY_UNDERFLOW, 0, 0, 0, 0);
  }
  const int64_t nsv = (int64_t)nSigsIn;              // decodeNum .ok arm
  if (nsv < 0 || nkv < nsv) return cms_pack_layout(LAY_SIG_COUNT, 0, 0, 0, 0);
  const uint32_t nSigs = (uint32_t)nsv;
  if (depth < (uint64_t)nKeys + (uint64_t)nSigs + 3u) {
    return cms_pack_layout(LAY_UNDERFLOW, 0, 0, 0, 0);
  }
  return cms_pack_layout(LAY_OK, nKeys, nSigs, nKeys + 2u, nKeys + 3u);
}
